void flex_lex_open(Lex *lx, FILE *f, const char *fname) {
    yyscan_t sc;
    yylex_init(&sc);
    yy_switch_to_buffer(yy_create_buffer(f, YY_BUF_SIZE, sc), sc);
    lineno = 1;
    lx->_scanner = sc;
    lx->_extra   = NULL;
    (void)fname;
}
/*----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/
/*----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/
#define SNO_END_NONE   ((void *)0)
#define SNO_END_ARMED  ((void *)1)
#define SNO_END_CLOSED ((void *)2)
int sno_end_lineno = 0;
Token flex_lex_next(Lex *lx) {
    yyscan_t sc = (yyscan_t)lx->_scanner;
    for (;;) {
        int r;
        if (lx->_extra == SNO_END_CLOSED) { Token e; e.kind = T_EOF; e.sval = NULL; e.ival = 0; e.dval = 0.0; e.lineno = lineno; return e; }
        r = yylex(sc);
        Token t;
        t.lineno = lineno;
        t.ival   = 0;
        t.dval   = 0.0;
        t.sval   = NULL;
        t.kind   = r;
        if (r == T_STMT_END) g_list_nends++;
        if (r == T_STMT_END && lx->_extra == SNO_END_ARMED) { lx->_extra = SNO_END_CLOSED; sno_end_lineno = lineno; }
        switch (r) {
        case T_EOF:
            t.kind = T_EOF; return t;
        case T_LABEL:
            t.sval = intern(strbuf);
            t.ival = strcmp(strbuf,"END")==0 ? 1 : 0;
            t.lineno = g_stmt_pos.lineno;
            if (t.ival) lx->_extra = SNO_END_ARMED;
            return t;
        case T_IDENT: case T_END: case T_KEYWORD:
        case T_FUNCTION:
        case T_GOTO_S: case T_GOTO_F:
            t.sval = intern(strbuf);
            return t;
        case T_STR:
            t.sval = intern(strbuf);
            return t;
        case T_INT:
            { long _iv = 0; int _ov = 0;
              for (const char *_q = strbuf; *_q >= '0' && *_q <= '9'; _q++) if (__builtin_mul_overflow(_iv, 10L, &_iv) || __builtin_add_overflow(_iv, (long)(*_q - '0'), &_iv)) _ov = 1;
              if (_ov) { sno_error(lineno, "syntax error: invalid numeric item"); _iv = 0; }
              t.ival = _iv; }
            return t;
        case T_REAL:
            t.sval = intern(strbuf);
            { extern int rt_gtn_real(const char *, long, double *); char *_ne = (char *)0; errno = 0; double _rv = 0.0;
              if (!rt_gtn_real(strbuf, (long)strlen(strbuf), &_rv)) _rv = strtod(strbuf, &_ne);
              if (!isfinite(_rv)) { sno_error(lineno, "syntax error: invalid numeric item"); _rv = 0.0; }
              t.dval = _rv; }
            return t;
        default:
            return t;
        }
    }
}
